/**
 *
 * Shared DnD type definitions used across createDnd, headless hooks, and components.
 *
 * @module Dnd
 * @group shared
 *
 */
export type UniqueId = string | number;
export type DragData = Record<string, unknown>;
export type CollisionStrategy = 'pointerWithin' | 'rectIntersection' | 'closestCenter' | 'closestCorners';
export type SortDirection = 'vertical' | 'horizontal' | 'grid';
export interface Point {
    x: number;
    y: number;
}
export interface Rect {
    x: number;
    y: number;
    width: number;
    height: number;
    top: number;
    right: number;
    bottom: number;
    left: number;
}
export interface Transform {
    x: number;
    y: number;
    scaleX: number;
    scaleY: number;
}
export interface DraggableRegistration {
    id: UniqueId;
    node: HTMLElement | null;
    disabled?: boolean;
    scope?: string;
    get data(): DragData;
}
export interface DroppableRegistration {
    id: UniqueId;
    node: HTMLElement | null;
    disabled?: boolean;
    accept?: string[];
    data?: DragData;
    canDrop?: (activeData: DragData) => boolean;
}
export interface SortableContainerRegistration {
    id: UniqueId;
    node: HTMLElement | null;
    items: UniqueId[];
    direction: SortDirection;
    scope?: string;
    accept?: string[];
    disabled?: boolean;
    /** When true, enables three-zone detection (before/inside/after) for Tree-like nested drops. */
    allowInsideDrop?: boolean;
}
export interface DragStartEvent {
    active: {
        id: UniqueId;
        data: DragData;
        node: HTMLElement | null;
    };
    event: Event;
}
export interface DragMoveEvent {
    active: {
        id: UniqueId;
        data: DragData;
        node: HTMLElement | null;
    };
    position: Point;
    delta: Point;
    event: Event;
}
export interface DragOverEvent {
    active: {
        id: UniqueId;
        data: DragData;
    };
    over: {
        id: UniqueId;
        data: DragData;
    } | null;
    event?: Event;
}
export interface DragEndEvent {
    active: {
        id: UniqueId;
        data: DragData;
    };
    over: {
        id: UniqueId;
        data: DragData;
    } | null;
    cancelled: boolean;
    event?: Event;
}
export interface DragCancelEvent {
    active: {
        id: UniqueId;
        data: DragData;
    };
    event?: Event;
}
export interface SortEvent {
    containerId: UniqueId;
    activeId: UniqueId;
    fromIndex: number;
    toIndex: number;
    event?: Event;
}
export interface TransferEvent {
    activeId: UniqueId;
    from: {
        containerId: UniqueId;
        index: number;
    };
    to: {
        containerId: UniqueId;
        index: number;
    };
    event?: Event;
}
export type DndEventMap = {
    dragStart: DragStartEvent;
    dragMove: DragMoveEvent;
    dragOver: DragOverEvent;
    dragEnd: DragEndEvent;
    dragCancel: DragCancelEvent;
    sort: SortEvent;
    transfer: TransferEvent;
};
export interface DragOperation {
    activeId: UniqueId;
    origin: Point;
    current: Point;
    delta: Point;
    data: DragData;
}
/** Where the dragged item would be placed relative to the target. */
export type DropPosition = 'before' | 'after' | 'inside';
/** Visual indicator data for rendering a drop line or highlight. */
export interface DropIndicator {
    /** The item closest to the pointer. */
    targetId: UniqueId;
    /** Placement relative to the target: 'before' (line above), 'after' (line below), 'inside' (highlight node). */
    position: DropPosition;
    /** Rect of the target item (scroll-adjusted). Useful for positioning the indicator. */
    targetRect: Rect | null;
}
export interface SortableOperationState {
    sourceContainerId: UniqueId;
    currentContainerId: UniqueId;
    originalIndex: number;
    projectedIndex: number;
    transforms: Map<UniqueId, Transform>;
    /** Drop indicator for rendering visual feedback (line between items or node highlight). */
    dropIndicator: DropIndicator | null;
}
export interface CollisionResult {
    id: UniqueId;
    data: DragData;
    ratio?: number;
    distance?: number;
}
export interface DndState {
    operation: DragOperation | null;
    draggables: Map<UniqueId, DraggableRegistration>;
    droppables: Map<UniqueId, DroppableRegistration>;
    sortableContainers: Map<UniqueId, SortableContainerRegistration>;
    collisions: CollisionResult[];
    sortable: SortableOperationState | null;
}
export interface PointerSensorOptions {
    activationDistance?: number;
    activationDelay?: number;
}
export interface KeyboardSensorOptions {
    step?: number;
    fastStep?: number;
}
export interface AutoScrollOptions {
    threshold?: number;
    speed?: number;
    direction?: 'vertical' | 'horizontal' | 'both';
}
export interface DndAnnouncements {
    onDragStart: (event: DragStartEvent) => string;
    onDragOver: (event: DragOverEvent) => string;
    onDragEnd: (event: DragEndEvent) => string;
    onDragCancel: (event: DragCancelEvent) => string;
    onSortOver: (info: {
        activeId: UniqueId;
        index: number;
        total: number;
        containerId?: UniqueId;
    }) => string;
}
export interface CreateDndOptions {
    collisionDetection?: CollisionStrategy;
    autoScroll?: boolean | AutoScrollOptions;
    announcements?: Partial<DndAnnouncements>;
}
export interface DndInstance {
    getState(): DndState;
    subscribe(listener: () => void): () => void;
    registerDraggable(reg: DraggableRegistration): () => void;
    registerDroppable(reg: DroppableRegistration): () => void;
    registerSortableContainer(reg: SortableContainerRegistration): () => void;
    startDrag(event: Event, activeId: UniqueId): void;
    updateDrag(event: Event, position: Point): void;
    endDrag(event?: Event): void;
    cancelDrag(event?: Event): void;
    on<K extends keyof DndEventMap>(event: K, handler: (event: DndEventMap[K]) => void): () => void;
    attachPointerSensor(element: HTMLElement, id: UniqueId, options?: PointerSensorOptions): () => void;
    attachKeyboardSensor(element: HTMLElement, id: UniqueId, options?: KeyboardSensorOptions): () => void;
    setScrollableElement(element: HTMLElement | null): void;
    setCollisionDetection(strategy: CollisionStrategy): void;
    measureRects(): void;
    getAdjustedRect(id: UniqueId, scrollDelta: Point): Rect | null;
    getAnnouncement<K extends keyof DndAnnouncements>(type: K, event: Parameters<DndAnnouncements[K]>[0]): string;
    destroy(): void;
}
